using namespace std;
const int MAXNODES = 5005;
const int MAXEDGES = 4 * MAXNODES * sqrt(MAXNODES);
const int INF_VAL = 1e9;
struct flowStruct { int c, f; };
int n, m, k, c, d, s, t, total, pre[MAXNODES];
int head[MAXNODES], edgeIdx = 1;
struct Edge {
	int to, next, val, w;
