void connectEdge(int u, int v, int val, int w) {
	++edgeIdx;
	e[edgeIdx].next = head[u];
	e[edgeIdx].w = w;
	e[edgeIdx].to = v;
	e[edgeIdx].val = val;
	head[u] = edgeIdx;
